<div class="page-head"><div><span class="eyebrow">Access Control</span><h1><?=e($title)?></h1><p>Assign a user to a business or create another super admin.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?=url('admin-users')?>">Back</a><?php if($user):?><a class="btn btn-primary" href="<?=url('admin-user-password',['id'=>$user['id']])?>">Reset Password</a><?php endif;?></div></div><form method="post" class="panel form-panel"><?=csrf_field()?><div class="form-grid two"><label>Full name<input name="name" required value="<?=e($_POST['name']??$user['name']??'')?>"></label><label>Email<input type="email" name="email" required value="<?=e($_POST['email']??$user['email']??'')?>"></label><label>Role<select name="role" data-role-select><option value="business_user" <?=($_POST['role']??$user['role']??'business_user')==='business_user'?'selected':''?>>Business User</option><option value="super_admin" <?=($_POST['role']??$user['role']??'')==='super_admin'?'selected':''?>>Super Admin</option></select></label><label data-business-field>Business<select name="business_id"><option value="">Select business</option><?php foreach($businesses as $b):?><option value="<?=$b['id']?>" <?=(string)($_POST['business_id']??$user['business_id']??'')===(string)$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label data-business-field>Provider KPI access<select name="provider_kpi_role"><option value="none" <?=($_POST['provider_kpi_role']??$user['provider_kpi_role']??'none')==='none'?'selected':''?>>Standard Viewer — read-only clinic dashboard</option><option value="leadership" <?=($_POST['provider_kpi_role']??$user['provider_kpi_role']??'')==='leadership'?'selected':''?>>Leadership — all providers, goals, imports, coaching</option><option value="data_uploader" <?=($_POST['provider_kpi_role']??$user['provider_kpi_role']??'')==='data_uploader'?'selected':''?>>Data Uploader — imports and clinic view</option><option value="provider" <?=($_POST['provider_kpi_role']??$user['provider_kpi_role']??'')==='provider'?'selected':''?>>Provider — own scorecard only</option></select><small>When the module is enabled, Standard Viewer can see the read-only clinic dashboard. Provider access requires linking this user to a provider profile.</small></label><?php if(!$user):?><label>Initial password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><?php else:?><div class="form-note"><strong>Password security</strong><span>Use the dedicated Reset Password page to replace this user’s password and optionally require a change at the next login.</span></div><?php endif;?><label>Status<select name="status"><option value="active" <?=($_POST['status']??$user['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($_POST['status']??$user['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label></div><button class="btn btn-primary" type="submit">Save User</button></form>
